const clock = (n:number) => `${Math.floor((n||0)/60).toString().padStart(2,'0')}:${Math.floor((n||0)%60).toString().padStart(2,'0')}`;
const precise = (n:number) => clock(n)+'.'+Math.floor(((n||0)%1)*100).toString().padStart(2,'0');
class ApiError extends Error { constructor(message:string,public status:number){super(message);this.name='ApiError';} }
async function api<T=any>(path:string, options:RequestInit={}):Promise<T> {
  const response = await fetch('/api'+path, {...options, headers:{'X-AIR3view':'studio', ...(options.body instanceof FormData ? {} : {'Content-Type':'application/json'}), ...options.headers}});
  const data = await response.json();
  if (!response.ok) throw new ApiError(typeof data.detail === 'string' ? data.detail : JSON.stringify(data.detail||data),response.status);
  return data;
}
function IconButton({label,onClick,children,disabled=false}:{label:string;onClick:()=>void;children:React.ReactNode;disabled?:boolean}) { return <button className="icon-button" title={label} aria-label={label} onClick={onClick} disabled={disabled}>{children}</button>; }
function Field({label,children,hint}:{label:string;children:React.ReactNode;hint?:string}) { return <label className="field"><span>{label}</span>{children}{hint&&<small>{hint}</small>}</label>; }
function Toggle({label,value,onChange}:{label:string;value:boolean;onChange:(x:boolean)=>void}) { return <label className="toggle-row"><span>{label}</span><input type="checkbox" checked={value} onChange={e=>onChange(e.target.checked)}/><i/></label>; }

