  useEffect(()=>{const handler=(e:KeyboardEvent)=>{if((e.ctrlKey||e.metaKey)&&e.key==='s'){e.preventDefault();persist().then(()=>setNotice('Đã lưu dự án')).catch(notify);}};window.addEventListener('keydown',handler);return()=>window.removeEventListener('keydown',handler);});
